import sys
import optax
sys.path.append('storage/noema/submissions')
# HDP‑RegCal core (dual‑path DSConv + heads + RegCal) used throughout
from dual_path_hybrid_motif_heads_regcal import build_network

BASE_SEED = 42
BATCH_SIZE = 64

def _define_hyperparameters():
    return {
        "learning_rate": 0.001,
        "weight_decay": 0.01,
        "head_dropout": 0.05,
        # other hparams are taken from the core implementation defaults
    }

def create_network(hparams):
    # Extract required parameters from hparams and delegate to the established HDP‑RegCal builder
    d_output = hparams.get("d_output", 1)
    task_type = hparams.get("task_type", "regression")
    return build_network(d_output, task_type, hparams)

def create_optimizer(learning_rate: float = 0.001):
    # Adopted default: clip=0.50, wd=0.01; refine AdamW b2 to 0.99
    return optax.chain(
        optax.clip_by_global_norm(0.50),
        optax.adamw(learning_rate=learning_rate, b1=0.9, b2=0.99, weight_decay=0.01),
    )

def complete(params, opt_state, trial_data):
    ds = trial_data.get('dataset'); vm = trial_data.get('val_metric')
    print(f"[Complete] {ds} val_metric={vm}")
